 "decisions": [
  {
   "title": "Data migrates to the target database",
   "context": "ORDENES and CUENTAS are VSAM KSDS files; the project's target is PostgreSQL.",
   "decision": "Both files become tables payment_orders and customer_accounts with the same key and the same numeric precision (decimal(11,2), decimal(13,2), decimal(5,2)). The FILLER of the order record is not migrated.",
   "consequences": "Data must be loaded once from the VSAM files. Keys are numeric columns: 7 and 5 digits for the order, 10 digits (long) for the account and the movement."
  },
  {
   "title": "Transaction owned by the REST adapter",
   "context": "PAGOORD works in one unit of work (begin at line 37, SYNCPOINT at line 172). Every rejection happens before any write is confirmed and returns a non-zero status with only the message.",
   "decision": "The REST adapter opens the transaction and commits at the end of PayOrder. A business error rolls everything back. The service does not call begin/commit/rollback itself, and there are no savepoints. The READ ... UPDATE of the legacy becomes SELECT ... FOR UPDATE on the order and the account.",
   "consequences": "In the target the debit and the order update are atomic. If PAGOMOV fails, the debit is undone, which the CICS program could not guarantee."
  },
  {
   "title": "PAGODEB becomes an in-process use case",
   "context": "PAGODEB is part of the migrated data domain. Its rules are in the approved set and its effect on CUENTAS is part of the golden master. PAGOORD LINKs to it.",
   "decision": "PAGODEB is the use case DebitAccount, which PayOrder invokes in the same transaction instead of a LINK. Its response codes (00/10/20/30/40) stay as data (DEB-RESP) and are not business errors. PayOrder maps them as the legacy does: 10 -> ACCOUNT_INACTIVE, 20 -> INSUFFICIENT_FUNDS, anything else -> INVALID_ACCOUNT.",
   "consequences": "No generated adapter is needed for PAGODEB. Rules 001-005 are implemented once."
  },
  {
   "title": "PAGOMOV is a port",
   "context": "PAGOMOV is not in the inputs and is called with LINK. The traces stub it with MOV_NUMERO.",
   "decision": "MovementGateway replaces PAGOMOV (legacy_program PAGOMOV, output MOV_NUMERO). It will be stubbed until its source is available.",
   "consequences": "The real behaviour of PAGOMOV is not covered by the golden master."
  },
  {
   "title": "Amount arrives as a decimal",
   "context": "The legacy reads VALORI as a screen string converted with NUMVAL(VALORI)/100, but the traces carry the amount as a decimal ('1500.00') and compare it directly with the order value.",
   "decision": "PayOrder receives the amount as decimal(11,2) and compares it with the order value by value (scale 2).",
   "consequences": "The screen string conversion is a UI concern and is not translated."
  },
  {
   "title": "Screens, keys and commarea are not translated",
   "context": "BMS maps, PF3/ENTER/other keys, the 13-byte commarea (CA-ULTIMA-ORDEN, CA-EMPRESA) and the pseudo-conversational RETURN TRANSID are CICS plumbing.",
   "decision": "REST endpoints replace the maps and key handling. The result of a payment is the response body. The menu use case only returns the destination. The last order in the commarea is not kept in the server.",
   "consequences": "A client that needs the last order must keep it itself."
  }
 ],
