package com.bank.payments.adapters.out.jdbc;

import com.bank.payments.domain.model.PaymentOrder;
import com.bank.payments.domain.port.OrderRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.math.BigDecimal;
import java.util.Optional;

/** JDBC adapter of the OrderRepository port (legacy file ORDENES). */
@Repository
public class JdbcOrderRepository implements OrderRepository {

    private final JdbcTemplate jdbcTemplate;

    public JdbcOrderRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    @Override
    public Optional<PaymentOrder> findByKey(Integer orderNumber, Integer companyId) {
        return jdbcTemplate.query(
                "SELECT order_number, company_id, status, order_value, movement_number, commission "
                        + "FROM payment_orders WHERE order_number = ? AND company_id = ? FOR UPDATE",
                rs -> {
                    if (!rs.next()) {
                        return Optional.<PaymentOrder>empty();
                    }
                    long movement = rs.getLong("movement_number");
                    Long movementNumber = rs.wasNull() ? null : movement;
                    return Optional.of(new PaymentOrder(
                            rs.getInt("order_number"),
                            rs.getInt("company_id"),
                            rs.getString("status"),
                            rs.getBigDecimal("order_value"),
                            movementNumber,
                            rs.getBigDecimal("commission")));
                },
                orderNumber, companyId);
    }

    @Override
    public int markPaid(Integer orderNumber, Integer companyId, Long movementNumber, BigDecimal commission) {
        return jdbcTemplate.update(
                "UPDATE payment_orders SET status = 'G', movement_number = ?, commission = ? "
                        + "WHERE order_number = ? AND company_id = ?",
                movementNumber, commission, orderNumber, companyId);
    }
}
